class Printer {
    // 만든 프린터를 보관해 두는 자리예요.
    private static Printer one;
    int jobs = 0;
    // 프린터를 돌려줘요.
    static Printer get() {
        return new Printer();
    }
    void print() {
        jobs++;
    }
}

public class Main {
    public static void main(String[] args) {
        int times = 2;
        Printer p1 = Printer.get();
        p1.print();
        Printer p2 = Printer.get();
        for (int i = 0; i < times; i++) {
            p2.print();
        }
        System.out.println(p1.jobs + " " + (p1 == p2));
    }
}

